<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Admin;use Acorn\SafetyHealthcheck\Database\Schema;final class DashboardPage{public function render():void{if(!current_user_can('manage_acorn_healthcheck'))wp_die('Forbidden',403);global$wpdb;$table=Schema::table('assessments');$started=(int)$wpdb->get_var("SELECT COUNT(*) FROM $table");$completed=(int)$wpdb->get_var("SELECT COUNT(*) FROM $table WHERE status='completed'");echo'<div class="wrap"><h1>Healthcheck Dashboard</h1><p>Starts: '.esc_html((string)$started).'</p><p>Completions: '.esc_html((string)$completed).'</p></div>';}}
